function total(prices) {
  const cents = prices.reduce((sum, p) => sum + Math.round(p * 100), 0);
  return Number((cents / 100).toFixed(2));
}

console.log(total([0.1, 0.2, 0.3]));
console.log(total([19.99, 5.01]));
